/* Small, optional game mechanics. No penalties, paywalls or persistent lives. */
let soundContext=null,gameTimer=null;
function playSound(kind){if(state.sound===false)return;try{const Context=window.AudioContext||window.webkitAudioContext;if(!Context)return;soundContext=soundContext||new Context();soundContext.resume();const notes=kind==='wrong'?[220,165]:kind==='win'?[523,659,784,1047]:kind==='match'?[659,880]:[523,659,784];notes.forEach((hz,i)=>{const oscillator=soundContext.createOscillator(),gain=soundContext.createGain(),at=soundContext.currentTime+i*.085;oscillator.type='sine';oscillator.frequency.value=hz;gain.gain.setValueAtTime(0,at);gain.gain.linearRampToValueAtTime(.07,at+.015);gain.gain.exponentialRampToValueAtTime(.001,at+.18);oscillator.connect(gain);gain.connect(soundContext.destination);oscillator.start(at);oscillator.stop(at+.2);});}catch(e){}}
function coach(text,mood='happy'){return `<div class="finn-coach ${mood}">${fox()}<div class="speech-bubble"><small>FINN SAYS</small><p>${escapeHTML(text)}</p></div></div>`;}
function confetti(){if(window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)return;const holder=document.createElement('div');holder.className='confetti';holder.setAttribute('aria-hidden','true');holder.innerHTML=Array.from({length:35},(_,i)=>`<i style="--x:${Math.random()*100}%;--r:${Math.random()*720}deg;--delay:${Math.random()*.4}s;--c:${['#6ecb49','#f7bb43','#65c8e0','#ff8e97','#aa8be0'][i%5]}"></i>`).join('');$('#lesson-dialog').appendChild(holder);setTimeout(()=>holder.remove(),2500);}
function initialiseGame(s){s.hearts=3;s.combo=0;s.maxCombo=0;s.bonus=0;s.typed='';if(s.type==='blitz'){s.phase='ready';s.remainingMs=60000;}}
function pauseTimer(){if(gameTimer){clearInterval(gameTimer);gameTimer=null;}if(session?.deadline){session.remainingMs=Math.max(0,session.deadline-Date.now());session.deadline=null;}}
function runTimer(){pauseTimer();const s=session;if(s?.type!=='blitz'||s.phase!=='question'||s.checked)return;s.deadline=Date.now()+s.remainingMs;gameTimer=setInterval(()=>{if(session!==s){pauseTimer();return;}s.remainingMs=Math.max(0,s.deadline-Date.now());const el=$('#timer-value');if(el)el.textContent=Math.ceil(s.remainingMs/1000)+'s';if(s.remainingMs<=0){pauseTimer();finishSession();}},200);}
function recordAnswer(s,q,right){if(right){s.correct++;s.combo++;s.maxCombo=Math.max(s.maxCombo,s.combo);if(s.combo%3===0)s.bonus+=5;state.mistakes=state.mistakes.filter(id=>id!==q.id);playSound(s.combo%3===0?'win':'correct');}else{s.combo=0;s.hearts=Math.max(0,s.hearts-1);if(!state.mistakes.includes(q.id))state.mistakes.push(q.id);playSound('wrong');}save();}
function numericAnswer(q){const answer=q.options[q.answer];return /^€?-?[\d,]+(?:\.\d+)?%?$/.test(answer)?Number(answer.replace(/[€,%]/g,'')):null;}
function parseNumber(text){const cleaned=String(text).trim().replace(/[€,%\s]/g,'');return cleaned!==''&&/^-?\d+(\.\d+)?$/.test(cleaned)?Number(cleaned):NaN;}
const MATCH_PAIRS=[
 ['Income','Money coming in'],['Expenditure','Money going out'],['Surplus','Income exceeds spending'],['Deficit','Spending exceeds income'],['Gross pay','Pay before deductions'],['Net pay','Pay after deductions'],['Premium','Price paid for insurance'],['Excess','Your contribution to a claim'],['Asset','Something a business owns'],['Liability','Something a business owes'],['Export','A sale to another country'],['Import','A purchase from abroad'],['Inflation','A rise in general prices'],['Revenue','A business’s sales income'],['Invoice','A request for payment'],['Receipt','Proof of payment'],['Primary research','Collecting new information'],['Promotion','Communicating a product’s offer'],['Opportunity cost','Next best alternative forgone'],['Capital','Equipment used in production']
];
function startMatching(){const pairs=shuffled(MATCH_PAIRS).slice(0,4).map((p,i)=>({id:i,term:p[0],definition:p[1]}));session={title:'Match Dash',type:'match',phase:'match',questions:pairs,index:0,correct:0,pairs,left:shuffled(pairs),right:shuffled(pairs),matched:[],picks:{},attempts:0,combo:0,maxCombo:0,bonus:0,hearts:3};showSession();$('#lesson-dialog').showModal();}
function matchMarkup(s){return `<div class="lesson-body"><div class="eyebrow">MATCH DASH · ${s.matched.length} / 4 PAIRS</div><h2>Two halves. One bright idea.</h2>${coach(s.matched.length?'Nice connection! Find the next pair.':'Tap a business word, then tap its meaning.')}<div class="match-board"><div>${s.left.map(p=>`<button class="match-tile ${s.matched.includes(p.id)?'matched':''} ${s.picks.term===p.id?'picked':''} ${s.mismatch&&s.picks.term===p.id?'mismatch':''}" data-match="${p.id}" data-side="term" ${s.matched.includes(p.id)||s.mismatch?'disabled':''}>${escapeHTML(p.term)}${s.matched.includes(p.id)?' ✓':''}</button>`).join('')}</div><div>${s.right.map(p=>`<button class="match-tile ${s.matched.includes(p.id)?'matched':''} ${s.picks.definition===p.id?'picked':''} ${s.mismatch&&s.picks.definition===p.id?'mismatch':''}" data-match="${p.id}" data-side="definition" ${s.matched.includes(p.id)||s.mismatch?'disabled':''}>${escapeHTML(p.definition)}${s.matched.includes(p.id)?' ✓':''}</button>`).join('')}</div></div><p class="match-hint" role="status">${s.mismatch?'Not quite a pair. Try a different connection.':'No timer. Just you and your business brain.'}</p></div>`;}
function bindMatching(){const s=session;$('#lesson-dialog').querySelectorAll('[data-match]').forEach(b=>b.onclick=()=>{if(s.mismatch)return;s.picks[b.dataset.side]=Number(b.dataset.match);if(s.picks.term!==undefined&&s.picks.definition!==undefined){s.attempts++;if(s.picks.term===s.picks.definition){s.matched.push(s.picks.term);s.correct++;s.combo++;s.maxCombo=Math.max(s.maxCombo,s.combo);s.picks={};playSound('match');if(s.matched.length===4){finishSession();return;}}else{s.combo=0;s.mismatch=true;playSound('wrong');setTimeout(()=>{if(session!==s||s.phase!=='match')return;s.mismatch=false;s.picks={};showSession();},750);}}showSession();});}
function arcadeMarkup(){return `<section class="arcade"><div class="section-title"><div><div class="eyebrow">THE BUSINESS ARCADE</div><h2>Play your way to “I’ve got this”.</h2></div><span class="arcade-label">✦ EARN BONUS XP</span></div><div class="arcade-grid"><article class="arcade-card match-card"><span class="arcade-art">▰<span>↔</span>▰</span><div><span class="mini-tag">QUICK CONNECTIONS</span><h3>Match Dash</h3><p>Pair the word with its meaning.<br>Four pairs. One satisfying finish.</p><button class="primary" id="match-btn">Let’s match →</button></div></article><article class="arcade-card blitz-card"><span class="arcade-art">ϟ<span>60s</span></span><div><span class="mini-tag">FEELING SPEEDY?</span><h3>Business Blitz</h3><p>60 seconds of answer time.<br>The clock pauses for explanations.</p><button class="primary" id="blitz-btn">Play the blitz →</button></div></article></div></section>`;}
function bindArcade(){$('#match-btn').onclick=startMatching;$('#blitz-btn').onclick=()=>startSession('Business Blitz',shuffled(STRANDS.flatMap(s=>shuffled(allQuestions().filter(q=>LESSONS.find(l=>l.id===q.lessonId).strand===s.id)).slice(0,4))),'blitz');}
